1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// 回归场景：交易在第 1 轮仍有效，但确认后进入的第 2 轮恰好等于它的到期轮次。
9	// 同一次确认要固定三个结果的先后关系：胜出交易只确认一次、保留竞争候选的
10	// 确认块标识与高度，不因进入到期轮次而变成过期；落选候选独有的交易先回到
11	// 排队、再按到期规则失效；未到期交易继续排队，且不能越过序号缺口被打包。
12	func TestConfirmIntoExpiryRoundKeepsWinnerConfirmed(t *testing.T) {
13		keys := genKeys(t, 4)
14		n, _ := newTestNode(t, keys, 2)
15	
16		// 两个发送者各提交序号 1：费用 10 与费用 5，到期轮次都为 2；
17		// 费用 5 的发送者另有序号 2、费用 100、到期轮次 100 的交易。
18		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 2)
19		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 2)
20		b2 := NewTransaction(keys[1].priv, 2, []byte("b2"), 100, 100)
21		for _, tx := range []*Transaction{a1, b1, b2} {
22			if _, err := n.Submit(tx); err != nil {
23				t.Fatal(err)
24			}
25		}
26	
27		// 本地提议包含两笔序号 1 交易（费用高者在前），序号 2 仍在排队。
28		local, err := n.Propose()
29		if err != nil {
30			t.Fatal(err)
31		}
32		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{a1.ID(), b1.ID()}) {
33			t.Fatalf("setup: local proposal = %v, want [a1 b1]", local.TxIDs)
34		}
35		if info, _ := n.Tx(b2.ID()); info.Status != StatusQueued {
36			t.Fatalf("setup: b2 status = %s, want queued", info.Status)
37		}
38	
39		// 竞争候选只包含费用 10 的那笔交易。
40		altID := registerMust(t, n, 1, []string{a1.ID()})
41		if altID == local.BlockID {
42			t.Fatal("test setup: competing candidate must differ from local proposal")
43		}
44	
45		// 两票计入但不确认：四人名单需严格超过三分之二，即三票。
46		for i := 0; i < 2; i++ {
47			res, err := n.Vote(keys[i].pub, 1, altID)
48			if err != nil || !res.Counted || res.Confirmed || res.Block != nil {
49				t.Fatalf("vote %d must count without confirming: %+v %v", i+1, res, err)
50			}
51		}
52		// 轮次与高度不前进，到期轮次为 2 的两笔交易仍有效，已确认序号不提前变化。
53		if n.CurrentRound() != 1 || n.Height() != 0 {
54			t.Fatalf("round=%d height=%d, want 1/0 before quorum", n.CurrentRound(), n.Height())
55		}
56		for _, id := range []string{a1.ID(), b1.ID()} {
57			info, err := n.Tx(id)
58			if err != nil {
59				t.Fatal(err)
60			}
61			if info.Status != StatusProposed {
62				t.Fatalf("tx %s status = %s, want proposed (still valid in round 1)", id, info.Status)
63			}
64		}
65		for _, k := range keys[:2] {
66			if acc := n.Account(k.pub); acc.ConfirmedSequence != 0 {
67				t.Fatalf("confirmed sequence = %d before quorum, want 0", acc.ConfirmedSequence)
68			}
69		}
70	
71		// 第三票使竞争候选胜出，并进入第 2 轮。
72		res, err := n.Vote(keys[2].pub, 1, altID)
73		if err != nil || !res.Counted || !res.Confirmed || res.Block == nil {
74			t.Fatalf("third vote should confirm: %+v %v", res, err)
75		}
76		if res.Block.ID != altID || res.Block.Height != 1 || res.Block.Round != 1 ||
77			fmt.Sprint(res.Block.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
78			t.Fatalf("confirming block wrong: %+v", res.Block)
79		}
80		if n.CurrentRound() != 2 || n.Height() != 1 {
81			t.Fatalf("round=%d height=%d, want 2/1 after confirm", n.CurrentRound(), n.Height())
82		}
83	
84		// 胜出交易虽也在落选的本地提议中，仍只确认一次：保留竞争候选对应的
85		// 确认块标识与高度，不能因进入其到期轮次（第 2 轮）而变成过期。
86		info, err := n.Tx(a1.ID())
87		if err != nil {
88			t.Fatal(err)
89		}
90		if info.Status != StatusConfirmed || info.BlockID != altID || info.BlockHeight != 1 {
91			t.Fatalf("winner tx wrong: %+v", info)
92		}
93		blk, err := n.BlockAt(1)
94		if err != nil {
95			t.Fatal(err)
96		}
97		if blk.ID != altID || blk.Height != 1 || blk.Round != 1 || blk.PreviousID != "" ||
98			fmt.Sprint(blk.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
99			t.Fatalf("stored block wrong: %+v", blk)
100		}
101		if latest, ok := n.LatestBlock(); !ok || latest.ID != altID {
102			t.Fatalf("latest block = %+v ok=%v, want competing candidate block", latest, ok)
103		}
104		// 胜出账户：已确认序号推进到 1，待处理列表移除该交易。
105		if accA := n.Account(keys[0].pub); accA.ConfirmedSequence != 1 || len(accA.Pending) != 0 {
106			t.Fatalf("winner account wrong: %+v", accA)
107		}
108	
109		// 另一笔序号 1 交易只属于落选候选：进入第 2 轮后显示 expired，
110		// 保留原交易内容，不留确认块关联，也不推进该账户的已确认序号。
111		info, err = n.Tx(b1.ID())
112		if err != nil {
113			t.Fatal(err)
114		}
115		if info.Status != StatusExpired || info.BlockID != "" || info.BlockHeight != 0 {
116			t.Fatalf("losing-only tx wrong: %+v", info)
117		}
118		if info.Tx == nil || info.Tx.Sequence != 1 || info.Tx.Fee != 5 || info.Tx.Expiry != 2 ||
119			string(info.Tx.Content) != "b1" {
120			t.Fatalf("expired tx must keep original content: %+v", info.Tx)
121		}
122		accB := n.Account(keys[1].pub)
123		if accB.ConfirmedSequence != 0 {
124			t.Fatalf("loser confirmed sequence = %d, want 0", accB.ConfirmedSequence)
125		}
126	
127		// 序号 2 交易尚未到期，继续以 queued 留在待处理列表，最早缺口为 1。
128		if accB.Gap != 1 {
129			t.Fatalf("earliest gap = %d, want 1", accB.Gap)
130		}
131		if len(accB.Pending) != 1 || accB.Pending[0].ID != b2.ID() ||
132			accB.Pending[0].Status != StatusQueued || accB.Pending[0].Note != "waiting-pack" {
133			t.Fatalf("loser pending wrong: %+v", accB.Pending)
134		}
135		if info, _ := n.Tx(b2.ID()); info.Status != StatusQueued {
136			t.Fatalf("b2 status = %s, want queued", info.Status)
137		}
138	
139		// 即使费用最高，序号 2 交易也不能越过缺口进入第 2 轮提议：空块。
140		prop2, err := n.Propose()
141		if err != nil {
142			t.Fatal(err)
143		}
144		if prop2.Round != 2 || !prop2.Empty || len(prop2.TxIDs) != 0 {
145			t.Fatalf("round 2 proposal = %+v, want empty block", prop2)
146		}
147	
148		// 候选历史：竞争候选胜出、本地提议落选，各自保留原来的交易顺序。
149		rc, err := n.Candidates(1)
150		if err != nil {
151			t.Fatal(err)
152		}
153		if !rc.Ended || rc.UnconfirmedEnd || len(rc.Unvoted) != 1 {
154			t.Fatalf("round 1 record wrong: %+v", rc)
155		}
156		altView := findCandidate(t, n, 1, altID)
157		if altView.Result != CandidateWon || len(altView.Voters) != 3 ||
158			fmt.Sprint(altView.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
159			t.Fatalf("winner candidate view wrong: %+v", altView)
160		}
161		localView := findCandidate(t, n, 1, local.BlockID)
162		if localView.Result != CandidateLost || !localView.Local ||
163			fmt.Sprint(localView.TxIDs) != fmt.Sprint([]string{a1.ID(), b1.ID()}) {
164			t.Fatalf("losing local candidate view wrong: %+v", localView)
165		}
166	
167		// 历史引用不能把过期交易重新变成等待投票，也不改变待处理列表。
168		if info, _ := n.Tx(b1.ID()); info.Status != StatusExpired {
169			t.Fatalf("expired tx revived by history query: %s", info.Status)
170		}
171		if accB := n.Account(keys[1].pub); len(accB.Pending) != 1 || accB.Pending[0].ID != b2.ID() {
172			t.Fatalf("history query changed pending list: %+v", accB.Pending)
173		}
174	}
