1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// findCandidate 在指定轮次中按区块标识找出候选视图，找不到即失败。
9	func findCandidate(t *testing.T, n *Node, round uint64, blockID string) CandidateView {
10		t.Helper()
11		rc, err := n.Candidates(round)
12		if err != nil {
13			t.Fatalf("candidates round %d: %v", round, err)
14		}
15		for _, c := range rc.Candidates {
16			if c.BlockID == blockID {
17				return c
18			}
19		}
20		t.Fatalf("candidate %s not found in round %d", blockID, round)
21		return CandidateView{}
22	}
23	
24	// assertRoundStillOpen 断言第 1 轮在达到门槛之前一切照旧：
25	// 投票已计入但结果仍为未决，轮次与确认高度不前进，候选引用的交易仍等待投票。
26	// candidateVoters 为该候选当前得票，totalVoted 为本轮已投票的不同验证者人数
27	// （票数分散到多个候选时二者不同）。
28	func assertRoundStillOpen(t *testing.T, n *Node, blockID string, totalValidators, candidateVoters, totalVoted int, txID string) {
29		t.Helper()
30		if n.CurrentRound() != 1 {
31			t.Fatalf("round = %d, must stay 1 before quorum", n.CurrentRound())
32		}
33		if n.Height() != 0 {
34			t.Fatalf("height = %d, must stay 0 before quorum", n.Height())
35		}
36		if _, ok := n.LatestBlock(); ok {
37			t.Fatal("no confirmed block may exist before quorum")
38		}
39		rc, err := n.Candidates(1)
40		if err != nil {
41			t.Fatal(err)
42		}
43		if rc.Ended {
44			t.Fatalf("round must not be decided before quorum: %+v", rc)
45		}
46		c := findCandidate(t, n, 1, blockID)
47		if c.Result != CandidatePending {
48			t.Fatalf("candidate result = %s, want pending", c.Result)
49		}
50		if len(c.Voters) != candidateVoters {
51			t.Fatalf("candidate voters = %d, want %d", len(c.Voters), candidateVoters)
52		}
53		if len(rc.Unvoted) != totalValidators-totalVoted {
54			t.Fatalf("unvoted = %d, want %d (full validator set always counts)",
55				len(rc.Unvoted), totalValidators-totalVoted)
56		}
57		if txID != "" {
58			info, err := n.Tx(txID)
59			if err != nil {
60				t.Fatal(err)
61			}
62			if info.Status != StatusProposed {
63				t.Fatalf("referenced tx status = %s, want proposed while pending", info.Status)
64			}
65		}
66	}
67	
68	// 确认规则是“某候选自己的有效票数严格超过完整验证者名单的三分之二”。
69	// 逐一名单规模保护确认时机：1 人第一票即确认；3 人两票未决、第三票确认；
70	// 5 人三票不足、四票足够（未投票的第五人不阻止）；6 人四票恰好三分之二仍不足，
71	// 第五票才确认。门槛只取决于完整名单人数，与实际参与投票的人数无关。
72	func TestQuorumAcrossValidatorSetSizes(t *testing.T) {
73		cases := []struct {
74			name         string
75			size         int
76			pendingVotes int // 达到门槛前逐票计入但保持未决的票数
77		}{
78			{"single-validator-first-vote-confirms", 1, 0},
79			{"three-validators-need-all-three", 3, 2},
80			{"five-validators-four-suffice-with-one-silent", 5, 3},
81			{"six-validators-exact-two-thirds-insufficient", 6, 4},
82		}
83		for _, tc := range cases {
84			t.Run(tc.name, func(t *testing.T) {
85				keys := genKeys(t, tc.size)
86				n, _ := newTestNode(t, keys, 10)
87				a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
88				if _, err := n.Submit(a1); err != nil {
89					t.Fatal(err)
90				}
91				local, _ := n.Propose()
92				if len(local.TxIDs) != 1 || local.TxIDs[0] != a1.ID() {
93					t.Fatalf("setup: local proposal = %v, want [a1]", local.TxIDs)
94				}
95	
96				// 门槛之前：每一票都正常计入，但不得表示已确认，轮次/高度/查询结果均不前进。
97				for i := 0; i < tc.pendingVotes; i++ {
98					res, err := n.Vote(keys[i].pub, 1, local.BlockID)
99					if err != nil || !res.Counted {
100						t.Fatalf("vote %d should be counted: %+v %v", i+1, res, err)
101					}
102					if res.Confirmed || res.Block != nil {
103						t.Fatalf("vote %d must not confirm (strictly more than 2/3 required): %+v", i+1, res)
104					}
105					assertRoundStillOpen(t, n, local.BlockID, tc.size, i+1, i+1, a1.ID())
106				}
107	
108				// 达到门槛的那一票立即返回胜出候选的确认块。
109				res, err := n.Vote(keys[tc.pendingVotes].pub, 1, local.BlockID)
110				if err != nil || !res.Counted || !res.Confirmed || res.Block == nil {
111					t.Fatalf("vote %d should confirm immediately: %+v %v", tc.pendingVotes+1, res, err)
112				}
113				wantVoters := tc.pendingVotes + 1
114				if res.Block.Height != 1 || res.Block.Round != 1 || res.Block.ID != local.BlockID {
115					t.Fatalf("confirming vote returned wrong block: %+v", res.Block)
116				}
117				if fmt.Sprint(res.Block.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
118					t.Fatalf("confirming block tx order = %v, want [a1]", res.Block.TxIDs)
119				}
120				if res.Block.PreviousID != "" {
121					t.Fatalf("genesis previous id = %q, want empty", res.Block.PreviousID)
122				}
123	
124				// 立即进入下一轮，确认高度前进；未投票者不阻止确认。
125				if n.CurrentRound() != 2 || n.Height() != 1 {
126					t.Fatalf("after confirm round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
127				}
128	
129				// 查询旧轮：候选胜出、得票与实际一致，未投票者仍按完整名单列出。
130				rc, err := n.Candidates(1)
131				if err != nil {
132					t.Fatal(err)
133				}
134				if !rc.Ended || rc.UnconfirmedEnd {
135					t.Fatalf("old round record wrong: %+v", rc)
136				}
137				c := findCandidate(t, n, 1, local.BlockID)
138				if c.Result != CandidateWon {
139					t.Fatalf("candidate result = %s, want won", c.Result)
140				}
141				if len(c.Voters) != wantVoters {
142					t.Fatalf("winner voters = %d, want %d", len(c.Voters), wantVoters)
143				}
144				if len(rc.Unvoted) != tc.size-wantVoters {
145					t.Fatalf("unvoted after confirm = %d, want %d", len(rc.Unvoted), tc.size-wantVoters)
146				}
147	
148				// 确认块标识与交易顺序来自胜出候选，交易已确认在高度 1。
149				blk, err := n.BlockAt(1)
150				if err != nil {
151					t.Fatal(err)
152				}
153				if blk.ID != local.BlockID || fmt.Sprint(blk.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
154					t.Fatalf("stored block wrong: %+v", blk)
155				}
156				info, _ := n.Tx(a1.ID())
157				if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != local.BlockID {
158					t.Fatalf("winner tx wrong after confirm: %+v", info)
159				}
160			})
161		}
162	}
163	
164	// 空块沿用同一票数规则：没有交易不免除投票，也不改变门槛。
165	func TestEmptyBlockUsesSameQuorum(t *testing.T) {
166		cases := []struct {
167			name         string
168			size         int
169			pendingVotes int
170		}{
171			{"single-empty-block", 1, 0},
172			{"three-validators-empty", 3, 2},
173			{"six-validators-empty", 6, 4},
174		}
175		for _, tc := range cases {
176			t.Run(tc.name, func(t *testing.T) {
177				keys := genKeys(t, tc.size)
178				n, _ := newTestNode(t, keys, 10)
179				local, _ := n.Propose() // 池中无交易，产生空块。
180				if !local.Empty || len(local.TxIDs) != 0 {
181					t.Fatalf("setup: expected empty proposal, got %v", local.TxIDs)
182				}
183	
184				for i := 0; i < tc.pendingVotes; i++ {
185					res, err := n.Vote(keys[i].pub, 1, local.BlockID)
186					if err != nil || !res.Counted || res.Confirmed {
187						t.Fatalf("empty-block vote %d must count without confirming: %+v %v", i+1, res, err)
188					}
189				}
190				res, err := n.Vote(keys[tc.pendingVotes].pub, 1, local.BlockID)
191				if err != nil || !res.Confirmed || res.Block == nil {
192					t.Fatalf("empty block should confirm on vote %d: %+v %v", tc.pendingVotes+1, res, err)
193				}
194				if len(res.Block.TxIDs) != 0 || res.Block.ID != local.BlockID {
195					t.Fatalf("confirmed empty block wrong: %+v", res.Block)
196				}
197				if n.CurrentRound() != 2 || n.Height() != 1 {
198					t.Fatalf("round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
199				}
200				blk, _ := n.BlockAt(1)
201				if blk.ID != local.BlockID || len(blk.TxIDs) != 0 {
202					t.Fatalf("stored empty block wrong: %+v", blk)
203				}
204			})
205		}
206	}
207	
208	// 票数归属与完整名单计数：六人名单中一个候选四票、另一个候选一票，
209	// 五个人已投票仍不能确认任何候选——未投票者始终计入名单人数，比例不能拿
210	// 实际参与人数计算。最后一人投给已有四票的候选后，它才得到足够的五票。
211	// 胜出者不是本地提议时，确认块的标识与交易顺序仍来自胜出候选。
212	func TestQuorumVoteOwnershipAndNonLocalWinner(t *testing.T) {
213		keys := genKeys(t, 6)
214		n, _ := newTestNode(t, keys, 10)
215		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
216		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
217		n.Submit(a1)
218		n.Submit(b1)
219		local, _ := n.Propose() // 打包按费用：b1 先、a1 后。
220		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{b1.ID(), a1.ID()}) {
221			t.Fatalf("setup: local proposal = %v, want [b1 a1]", local.TxIDs)
222		}
223		// 竞争候选使用相反的交易顺序，将作为非本地候选胜出。
224		altList := []string{a1.ID(), b1.ID()}
225		altID := registerMust(t, n, 1, altList)
226		if altID == local.BlockID {
227			t.Fatal("test setup: alt candidate must differ from local")
228		}
229	
230		// 四人投竞争候选：4 票恰好等于六人的三分之二，仍不足。
231		for i := 0; i < 4; i++ {
232			res, err := n.Vote(keys[i].pub, 1, altID)
233			if err != nil || !res.Counted || res.Confirmed {
234				t.Fatalf("alt vote %d must count without confirming: %+v %v", i+1, res, err)
235			}
236		}
237		// 第五人投本地候选：两个候选分别为 4 票与 1 票，均不能确认。
238		res, err := n.Vote(keys[4].pub, 1, local.BlockID)
239		if err != nil || !res.Counted || res.Confirmed {
240			t.Fatalf("local vote must count without confirming: %+v %v", res, err)
241		}
242		if n.CurrentRound() != 1 || n.Height() != 0 {
243			t.Fatalf("round=%d height=%d, split 4/1 votes must not decide", n.CurrentRound(), n.Height())
244		}
245		altView := findCandidate(t, n, 1, altID)
246		localView := findCandidate(t, n, 1, local.BlockID)
247		if altView.Result != CandidatePending || len(altView.Voters) != 4 {
248			t.Fatalf("alt candidate wrong before quorum: %+v", altView)
249		}
250		if localView.Result != CandidatePending || len(localView.Voters) != 1 {
251			t.Fatalf("local candidate wrong before quorum: %+v", localView)
252		}
253		rc, _ := n.Candidates(1)
254		if len(rc.Unvoted) != 1 || fmt.Sprintf("%x", rc.Unvoted[0]) != fmt.Sprintf("%x", keys[5].pub) {
255			t.Fatalf("only keys[5] should be unvoted: %x", rc.Unvoted)
256		}
257		// 两笔交易仍处于等待投票状态。
258		for _, id := range []string{a1.ID(), b1.ID()} {
259			if info, _ := n.Tx(id); info.Status != StatusProposed {
260				t.Fatalf("tx %s status = %s, want proposed", id, info.Status)
261			}
262		}
263	
264		// 重复投原候选不增票，不能借重复请求跨过门槛；改投仍被一人一轮一票规则拒绝。
265		dup, err := n.Vote(keys[0].pub, 1, altID)
266		if err != nil || dup.Counted || dup.Confirmed {
267			t.Fatalf("duplicate vote must not count or confirm: %+v %v", dup, err)
268		}
269		if _, err := n.Vote(keys[0].pub, 1, local.BlockID); reason(err) != ReasonAlreadyVoted {
270			t.Fatalf("switching candidate got %v, want %s", err, ReasonAlreadyVoted)
271		}
272		assertRoundStillOpen(t, n, altID, 6, 4, 5, a1.ID())
273	
274		// 最后一名未投票者投给已有四票的候选：第五票严格超过三分之二，立即确认。
275		res, err = n.Vote(keys[5].pub, 1, altID)
276		if err != nil || !res.Counted || !res.Confirmed || res.Block == nil {
277			t.Fatalf("fifth distinct alt vote should confirm: %+v %v", res, err)
278		}
279		if n.CurrentRound() != 2 || n.Height() != 1 {
280			t.Fatalf("round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
281		}
282		// 确认块标识与交易顺序来自非本地的胜出候选。
283		if res.Block.ID != altID || fmt.Sprint(res.Block.TxIDs) != fmt.Sprint(altList) {
284			t.Fatalf("confirming block must come from non-local winner: %+v", res.Block)
285		}
286		blk, _ := n.BlockAt(1)
287		if blk.ID != altID || fmt.Sprint(blk.TxIDs) != fmt.Sprint(altList) || blk.PreviousID != "" {
288			t.Fatalf("stored block must match non-local winner: %+v", blk)
289		}
290	
291		// 查询旧轮：胜出者与落选者的结果和实际得票一一对应，投票者不重复。
292		rc, _ = n.Candidates(1)
293		if !rc.Ended || rc.UnconfirmedEnd || len(rc.Unvoted) != 0 {
294			t.Fatalf("decided round record wrong: %+v", rc)
295		}
296		altView = findCandidate(t, n, 1, altID)
297		localView = findCandidate(t, n, 1, local.BlockID)
298		if altView.Result != CandidateWon || len(altView.Voters) != 5 {
299			t.Fatalf("winner view wrong: %+v", altView)
300		}
301		wantAltVoters := map[string]bool{}
302		for _, i := range []int{0, 1, 2, 3, 5} {
303			wantAltVoters[fmt.Sprintf("%x", keys[i].pub)] = true
304		}
305		gotAltVoters := map[string]bool{}
306		for _, v := range altView.Voters {
307			k := fmt.Sprintf("%x", v)
308			if gotAltVoters[k] {
309				t.Fatalf("voter %s appears more than once", k)
310			}
311			gotAltVoters[k] = true
312		}
313		if fmt.Sprint(gotAltVoters) != fmt.Sprint(wantAltVoters) {
314			t.Fatalf("winner voters = %v, want %v", gotAltVoters, wantAltVoters)
315		}
316		if localView.Result != CandidateLost || len(localView.Voters) != 1 ||
317			fmt.Sprintf("%x", localView.Voters[0]) != fmt.Sprintf("%x", keys[4].pub) {
318			t.Fatalf("loser view must keep its single real vote: %+v", localView)
319		}
320	
321		// 胜出候选中的交易按其顺序确认一次。
322		for _, id := range altList {
323			info, _ := n.Tx(id)
324			if info.Status != StatusConfirmed || info.BlockID != altID || info.BlockHeight != 1 {
325				t.Fatalf("winner tx %s wrong: %+v", id, info)
326			}
327		}
328	}
