528	func proposalViewOf(round uint64, c *candidateState) ProposalView {
529		ids := append([]string(nil), c.TxIDs...)
530		return ProposalView{Round: round, BlockID: c.BlockID, TxIDs: ids, Empty: len(ids) == 0}
531	}
