574	// CandidateView 是一个已登记候选的只读视图。
575	type CandidateView struct {
576		// Round 候选所属轮次。
577		Round uint64
578		// BlockID 候选区块标识。
579		BlockID string
580		// TxIDs 候选中的交易顺序。
581		TxIDs []string
582		// Local 是否为本节点 Propose 产生的本地提议。
583		Local bool
584		// Voters 已投给该候选的验证者公钥，按公钥十六进制定序返回。
585		Voters [][]byte
